function manualTypes(data:Store){return Object.entries(data.libraryGroups||{}).filter(([key])=>key.startsWith('type::')).map(([key,group])=>({id:key.slice(6),group})).sort((a,b)=>(a.group.name||'').localeCompare(b.group.name||''))}
function manualLines(data:Store,typeId:string){const prefix=`line::${typeId}::`;return Object.entries(data.libraryGroups||{}).filter(([key])=>key.startsWith(prefix)).map(([key,group])=>({id:key.slice(prefix.length),group})).sort((a,b)=>(a.group.name||'').localeCompare(b.group.name||''))}
function groupName(data:Store,level:'type'|'line',typeId:string,lineId?:string){const key=level==='type'?libraryTypeGroupKey(typeId):libraryLineGroupKey(typeId,lineId||'');return data.libraryGroups?.[key]?.name?.trim()||(level==='type'?'Untitled type':'Untitled line')}
